mapper.select:
SELECT a.id AS auditId, a.dispatch_id AS dispatchId, a.action_by AS operatorId, op.real_name AS operatorName, dr.task_id AS taskId, dr.assignee_id AS assigneeId, asg.real_name AS assigneeName, dr.mode AS mode, t.work_order_id AS workOrderId, t.operation_code AS operationCode, t.operation_name AS operationName, wo.erp_order_no AS erpOrderNo, a.snapshot_json AS snapshotJson, a.created_at AS createdAt FROM dispatch_audit_log a INNER JOIN dispatch_record dr ON a.dispatch_id = dr.id INNER JOIN operation_task t ON dr.task_id = t.id INNER JOIN work_order wo ON t.work_order_id = wo.id LEFT JOIN sys_user op ON a.action_by = op.id LEFT JOIN sys_user asg ON dr.assignee_id = asg.id
AND dr.task_id = #{taskId}
AND dr.assignee_id = #{assigneeId}
AND a.action_by = #{operatorId}
ORDER BY a.created_at DESC, a.id DESC
